    31          matches!(self, Self::Unordered)
    32      }
    33  }
    35  new_key_type! {
    36      pub struct EdgeKey;
    37  }
    39  type EdgesMap = SlotMap<EdgeKey, Edge>;
    41  pub fn simplify_and_fetch_orderings(
    42      roots: &[Node],
    43      ir_arena: &mut Arena<IR>,
    44      expr_arena: &mut Arena<AExpr>,
    45  ) -> (
    46      PlIndexMap<IRNodeKey, IRNodeEdgeKeys<EdgeKey>>,
    47      SlotMap<EdgeKey, Edge>,
    48  ) {
    49      let (mut ir_nodes_stack, mut ir_node_to_edges_map, mut all_edges_map, cache_updater) =
    50          build_ir_traversal_graph(roots, ir_arena);
    52      let eos_revisit_cache = &mut PlIndexMap::default();
    53      let ae_nodes_scratch = &mut ScratchVec::default();
    54      let mut deleted_idxs = vec![];
    56      let mut simplifier = SimplifyIRNodeOrder {
    57          ir_node_to_edges_map: &mut ir_node_to_edges_map,
    58          all_edges_map: &mut all_edges_map,
    59          ir_arena,
    60          expr_arena,
    61          eos_revisit_cache,
    62          ae_nodes_scratch,
    63      };
    65      for (i, node) in ir_nodes_stack.iter().copied().enumerate() {
    66          if simplifier.simplify_ir_node_orders(node) {
    67              deleted_idxs.push(i)
    68          }
    69      }
    71      for (i, node) in ir_nodes_stack.drain(..).enumerate().rev() {
    72          if deleted_idxs.last() == Some(&i) {
    73              deleted_idxs.pop();
    74              continue;
    75          }
    77          simplifier.simplify_ir_node_orders(node);
    78      }
    80      cache_updater.update_cache_nodes(ir_arena);
    83      for (key, edges) in ir_node_to_edges_map.iter() {
    84          if let Some(node) = key.node()
    85              && let IR::Scan { maintain_order, .. } = ir_arena.get_mut(node)
    86              && !edges.out_edges.is_empty()
    87              && edges
    88                  .out_edges
    89                  .iter()
    90                  .all(|k| all_edges_map.get(*k).unwrap().is_unordered())
    91          {
    92              *maintain_order = false;
    93          }
    94      }
    96      (ir_node_to_edges_map, all_edges_map)
    97  }
    99  struct SimplifyIRNodeOrder<'a> {
   100      ir_node_to_edges_map: &'a mut PlIndexMap<IRNodeKey, IRNodeEdgeKeys<EdgeKey>>,
   101      all_edges_map: &'a mut EdgesMap,
   102      ir_arena: &'a mut Arena<IR>,
   103      expr_arena: &'a mut Arena<AExpr>,
   104      eos_revisit_cache: &'a mut PlIndexMap<Node, ObservableOrders>,
   105      ae_nodes_scratch: &'a mut ScratchVec<Node>,
   106  }
   108  impl SimplifyIRNodeOrder<'_> {
   110      fn simplify_ir_node_orders(&mut self, current_ir_node: Node) -> bool {
   111          use ObservableOrders as O;
   113          let current_ir_node_edges = self
   114              .ir_node_to_edges_map
   115              .get(&IRNodeKey::new(current_ir_node, self.ir_arena))
   116              .unwrap();
   118          let IRNodeEdgeKeys {
   119              in_edges,
   120              out_edges,
   121              out_nodes: _,
   122          } = current_ir_node_edges;
   124          macro_rules! get_edge {
   125              ($edge_key:expr) => {
   126                  self.all_edges_map.get($edge_key).unwrap()
   127              };
   128          }
   130          macro_rules! get_edge_mut {
   131              ($edge_key:expr) => {
   132                  self.all_edges_map.get_mut($edge_key).unwrap()
   133              };
   134          }
   136          macro_rules! unpack_edges {
   137              ($total:literal) => {
   138                  unpack_edges_mut::<EdgeKey, Edge, _, _, $total>(
   139                      current_ir_node_edges,
   140                      self.all_edges_map,
   141                  )
   142                  .unwrap()
   143              };
   144          }
   146          macro_rules! expr_order_simplifier {
   147              () => {{
   148                  self.eos_revisit_cache.clear();
   149                  ExprOrderSimplifier::new(self.expr_arena, self.eos_revisit_cache)
   150              }};
   151          }
   153          match self.ir_arena.get_mut(current_ir_node) {
   154              IR::Select { .. } | IR::HStack { .. } => {
   155                  let (exprs, is_hstack) = match self.ir_arena.get_mut(current_ir_node) {
   156                      IR::Select { expr, .. } => (expr, false),
   157                      IR::HStack { exprs, schema, .. } => {
   158                          let v = schema.len() != exprs.len();
   159                          (exprs, v)
   160                      },
   161                      _ => unreachable!(),
   162                  };
   164                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   166                  let mut eos = expr_order_simplifier!();
   167                  let ae_nodes_scratch = self.ae_nodes_scratch.get();
   169                  ae_nodes_scratch.extend(exprs.iter().map(|eir| eir.node()));
   171                  let exprs_observable_orders = eos.simplify_projected_exprs(
   172                      ae_nodes_scratch,
   173                      out_edge.is_unordered() && (in_edge.is_unordered() || !is_hstack),
   174                  );
   176                  let input_order_observe = ((exprs_observable_orders.contains(O::COLUMN)
   177                      || is_hstack)
   178                      && !out_edge.is_unordered())
   179                      || (is_hstack && exprs_observable_orders.contains(O::INDEPENDENT))
   180                      || eos.internally_observed_orders().contains(O::COLUMN);
   182                  if !input_order_observe {
   183                      *in_edge = Edge::Unordered;
   184                  }
   186                  if !exprs_observable_orders.contains(O::INDEPENDENT)
   187                      && (in_edge.is_unordered()
   188                          || !(is_hstack || exprs_observable_orders.contains(O::COLUMN)))
   189                  {
   190                      *out_edge = Edge::Unordered;
   191                  }
   192              },
   194              IR::Sort {
   195                  input,
   196                  by_column,
   197                  slice,
   198                  sort_options,
   199              } => {
   200                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   202                  if let Some(kept) =
   203                      non_scalar_keys(by_column.iter().map(|e| e.node()), self.expr_arena)
   204                  {
   205                      if kept.is_empty() {
   206                          let input = *input;
   207                          let Some((offset, len, _)) = *slice else {
   208                              *in_edge = out_edge.clone();
   209                              return self.unlink_node(current_ir_node, input);
   210                          };
   211                          *self.ir_arena.get_mut(current_ir_node) = IR::Slice {
   212                              input,
   213                              offset,
   214                              len: len.try_into().unwrap_or(IdxSize::MAX),
   215                          };
   216                          return self.simplify_ir_node_orders(current_ir_node);
   217                      }
   218                      *by_column = kept.iter().map(|&i| by_column[i].clone()).collect();
   219                      sort_options.descending = flags_at(&sort_options.descending, &kept);
   220                      sort_options.nulls_last = flags_at(&sort_options.nulls_last, &kept);
   221                  }
   223                  if out_edge.is_unordered() && slice.is_none() {
   224                      *in_edge = out_edge.clone();
   225                      let input = *input;
   226                      return self.unlink_node(current_ir_node, input);
   227                  }
   229                  let mut eos = expr_order_simplifier!();
   230                  let ae_nodes_scratch = self.ae_nodes_scratch.get();
   232                  ae_nodes_scratch.extend(by_column.iter().map(|eir| eir.node()));
   234                  let key_exprs_observable_orders =
   235                      eos.simplify_projected_exprs(ae_nodes_scratch, false);
   237                  if in_edge.is_unordered()
   238                      || !(sort_options.maintain_order
   239                          || eos.internally_observed_orders().contains(O::COLUMN)
   240                          || key_exprs_observable_orders.contains(O::INDEPENDENT))
   241                  {
   242                      *in_edge = Edge::Unordered;
   243                      sort_options.maintain_order = false;
   244                  }
   245              },
   247              IR::Filter {
   248                  input: _,
   249                  predicate,
   250              } => {
   251                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   253                  let mut eos = expr_order_simplifier!();
   254                  let predicate_observable_orders =
   255                      eos.simplify_projected_exprs(&[predicate.node()], false);
   257                  if out_edge.is_unordered()
   258                      && !(eos.internally_observed_orders().contains(O::COLUMN)
   259                          || predicate_observable_orders.contains(O::INDEPENDENT))
   260                  {
   261                      *in_edge = Edge::Unordered;
   262                  }
   264                  if in_edge.is_unordered() {
   265                      *out_edge = Edge::Unordered;
   266                  }
   267              },
   269              IR::GroupBy {
   270                  input: _,
   271                  keys,
   272                  aggs,
   273                  schema: _,
   274                  maintain_order,
   275                  options,
   276                  apply,
   277              } => {
   278                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   281                  for agg in aggs.iter_mut() {
   282                      if !is_scalar_ae(agg.node(), self.expr_arena) {
   283                          agg.set_node(self.expr_arena.add(AExpr::Agg(IRAggExpr::Implode {
   284                              input: agg.node(),
   285                              maintain_order: true,
   286                          })));
   287                      }
   288                  }
   290                  let mut eos = expr_order_simplifier!();
   291                  let ae_nodes_scratch = self.ae_nodes_scratch.get();
   293                  ae_nodes_scratch.extend(keys.iter().map(|eir| eir.node()));
   294                  let keys_observable = eos.simplify_projected_exprs(
   295                      ae_nodes_scratch,
   296                      in_edge.is_unordered() && !*maintain_order,
   297                  );
   299                  ae_nodes_scratch.clear();
   300                  ae_nodes_scratch.extend(aggs.iter().map(|eir| eir.node()));
   301                  eos.simplify_projected_exprs(ae_nodes_scratch, false);
   303                  let order_observing_options =
   304                      apply.is_some() || options.is_dynamic() || options.is_rolling();
   306                  if !(order_observing_options
   307                      || keys_observable.contains(O::INDEPENDENT)
   308                      || eos.internally_observed_orders().contains(O::COLUMN)
   309                      || (*maintain_order
   310                          && keys_observable.contains(O::COLUMN)
   311                          && (!out_edge.is_unordered() || options.slice.is_some())))
   312                  {
   313                      *in_edge = Edge::Unordered;
   314                  }
   316                  if (out_edge.is_unordered() && options.slice.is_none())
   317                      || !*maintain_order
   318                      || (in_edge.is_unordered() && !keys_observable.contains(O::INDEPENDENT))
   319                  {
   320                      *out_edge = Edge::Unordered;
   321                      *maintain_order = false;
   322                  }
   323              },
   325              IR::Window {
   326                  order_by,
   327                  exprs,
   328                  maintain_order,
   329                  ordered_eval,
   330                  ..
   331              } => {
   332                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   334                  let ties_in_input_order = order_by
   335                      .as_ref()
   336                      .is_none_or(|(_, options)| options.maintain_order);
   337                  let observes = ties_in_input_order
   338                      && exprs
   339                          .iter()
   340                          .any(|e| !is_order_insensitive_window(e.node(), self.expr_arena));
   342                  if out_edge.is_unordered() {
   343                      *maintain_order = false;
   344                  }
   345                  *ordered_eval = observes;
   347                  if !*maintain_order && !observes {
   348                      *in_edge = Edge::Unordered;
   349                  }
   350              },
   352              IR::Distinct { input: _, options } => {
   353                  use UniqueKeepStrategy as K;
   355                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   357                  if !options.maintain_order || (out_edge.is_unordered() && options.slice.is_none()) {
   358                      options.maintain_order = false;
   359                      *out_edge = Edge::Unordered;
   360                  }
   362                  if in_edge.is_unordered()
   363                      || (!options.maintain_order
   364                          && match options.keep_strategy {
   365                              K::First | K::Last => false,
   366                              K::Any | K::None => true,
   367                          })
   368                  {
   369                      options.maintain_order = false;
   371                      match options.keep_strategy {
   372                          K::First | K::Last => options.keep_strategy = K::Any,
   373                          K::Any | K::None => {},
   374                      };
   376                      *in_edge = Edge::Unordered;
   377                  }
   378              },
   380              IR::Join {
   381                  input_left: _,
   382                  input_right: _,
   383                  schema: _,
   384                  options,
   385              } => {
   386                  use polars_defs::join::JoinType;
   388                  let ([in_edge_lhs, in_edge_rhs], [out_edge]) = unpack_edges!(3);
   390                  let ae_nodes_scratch = self.ae_nodes_scratch.get();
   392                  let mut eos = expr_order_simplifier!();
   393                  ae_nodes_scratch.extend(options.options.left_on().map(|eir| eir.node()));
   394                  let left_keys_observable = eos.simplify_projected_exprs(ae_nodes_scratch, false);
   396                  let left_keys_pin_order = eos.internally_observed_orders().contains(O::COLUMN);
   398                  ae_nodes_scratch.clear();
   399                  let mut eos = expr_order_simplifier!();
   400                  ae_nodes_scratch.extend(options.options.right_on().map(|eir| eir.node()));
   401                  let right_keys_observable = eos.simplify_projected_exprs(ae_nodes_scratch, false);
   402                  let right_keys_pin_order = eos.internally_observed_orders().contains(O::COLUMN);
   405                  assert!(!(left_keys_observable | right_keys_observable).contains(O::INDEPENDENT));
   408                  macro_rules! pin_key_orders {
   409                      () => {
   410                          if left_keys_pin_order {
   411                              *in_edge_lhs = Edge::Ordered;
   412                          }
   413                          if right_keys_pin_order {
   414                              *in_edge_rhs = Edge::Ordered;
   415                          }
   416                      };
   417                  }
   419                  #[cfg(feature = "asof_join")]
   420                  if let JoinType::AsOf(_) = &options.args.how {
   421                      if in_edge_lhs.is_unordered()
   422                          || (out_edge.is_unordered() && in_edge_rhs.is_unordered())
   423                      {
   424                          *in_edge_lhs = Edge::Unordered;
   425                          *in_edge_rhs = Edge::Unordered;
   426                          *out_edge = Edge::Unordered;
   427                      }
   429                      pin_key_orders!();
   430                      return false;
   431                  }
   433                  use polars_defs::join::MaintainOrderJoin as JO;
   435                  if out_edge.is_unordered() || options.args.maintain_order == JO::None {
   436                      *out_edge = Edge::Unordered;
   437                      *in_edge_lhs = Edge::Unordered;
   438                      *in_edge_rhs = Edge::Unordered;
   439                      Arc::make_mut(options).args.maintain_order = JO::None;
   440                  }
   442                  if in_edge_lhs.is_unordered() || options.args.maintain_order == JO::Right {
   443                      *in_edge_lhs = Edge::Unordered;
   445                      match options.args.maintain_order {
   446                          JO::Left => Arc::make_mut(options).args.maintain_order = JO::None,
   447                          JO::LeftRight | JO::RightLeft => {
   448                              Arc::make_mut(options).args.maintain_order = JO::Right
   449                          },
   450                          JO::None | JO::Right => {},
   451                      }
   452                  }
   454                  if in_edge_rhs.is_unordered()
   455                      || options.args.maintain_order == JO::Left
   456                      || match &options.args.how {
   457                          #[cfg(feature = "semi_anti_join")]
   458                          JoinType::Semi | JoinType::Anti => true,
   459                          _ => false,
   460                      }
   461                  {
   462                      *in_edge_rhs = Edge::Unordered;
   464                      match options.args.maintain_order {
   465                          JO::Right => Arc::make_mut(options).args.maintain_order = JO::None,
   466                          JO::RightLeft | JO::LeftRight => {
   467                              Arc::make_mut(options).args.maintain_order = JO::Left
   468                          },
   469                          JO::None | JO::Left => {},
   470                      }
   471                  }
   473                  pin_key_orders!();
   474              },
   476              IR::Gather { .. } => {
   478                  let ([_input_edge, idxs_edge], [out_edge]) = unpack_edges!(3);
   479                  if out_edge.is_unordered() {
   480                      *idxs_edge = Edge::Unordered;
   481                  }
   483                  if idxs_edge.is_unordered() {
   484                      *out_edge = Edge::Unordered;
   485                  }
   486              },
   488              IR::Union { inputs: _, options } => {
   489                  assert_eq!(out_edges.len(), 1);
   491                  let out_edge_key = *out_edges.first().unwrap();
   493                  if !options.maintain_order
   494                      || (get_edge!(out_edge_key).is_unordered() && options.slice.is_none())
   495                  {
   496                      options.maintain_order = false;
   497                      *get_edge_mut!(out_edge_key) = Edge::Unordered;
   498                      for k in in_edges.iter() {
   499                          *get_edge_mut!(*k) = Edge::Unordered;
   500                      }
   501                  }
   503              },
   505              #[cfg(feature = "merge_sorted")]
   506              IR::MergeSorted {
   507                  input_left,
   508                  input_right,
   509                  ..
   510              } => {
   511                  let ([in_edge_lhs, in_edge_rhs], [out_edge]) = unpack_edges!(3);
   513                  if out_edge.is_unordered()
   514                      || (in_edge_lhs.is_unordered() && in_edge_rhs.is_unordered())
   515                  {
   516                      *out_edge = Edge::Unordered;
   517                      *in_edge_lhs = Edge::Unordered;
   518                      *in_edge_rhs = Edge::Unordered;
   520                      let input_left = *input_left;
   521                      let input_right = *input_right;
   523                      self.ir_arena.replace(
   524                          current_ir_node,
   525                          IR::Union {
   526                              inputs: vec![input_left, input_right],
   527                              options: UnionOptions {
   528                                  maintain_order: false,
   529                                  ..Default::default()
   530                              },
   531                          },
   532                      );
   533                  }
   534              },
   536              IR::MapFunction { input: _, function } => {
   537                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   539                  if !function.observes_input_order()
   540                      && (!function.has_equal_order() || out_edge.is_unordered())
   541                  {
   542                      *in_edge = Edge::Unordered;
   543                  }
   545                  if !function.is_order_producing(!in_edge.is_unordered())
   546                      && (in_edge.is_unordered() || !function.has_equal_order())
   547                  {
   548                      *out_edge = Edge::Unordered;
   549                  }
   550              },
   552              IR::HConcat { .. } | IR::Slice { .. } => {
   553                  if in_edges.iter().all(|k| get_edge!(*k).is_unordered()) {
   554                      for k in out_edges.iter() {
   555                          *get_edge_mut!(*k) = Edge::Unordered
   556                      }
   557                  }
   558              },
   560              IR::SimpleProjection { .. } => {
   561                  let ([in_edge], [out_edge]) = unpack_edges!(2);
   563                  if in_edge.is_unordered() || out_edge.is_unordered() {
   564                      *in_edge = Edge::Unordered;
   565                      *out_edge = Edge::Unordered;
   566                  }
   567              },
   569              IR::Cache { .. } => {
   570                  assert_eq!(in_edges.len(), 1);
   572                  if get_edge!(in_edges[0]).is_unordered() {
   573                      for k in out_edges.iter() {
   574                          *get_edge_mut!(*k) = Edge::Unordered
   575                      }
   576                  } else if out_edges.iter().all(|k| get_edge!(*k).is_unordered()) {
   577                      *get_edge_mut!(in_edges[0]) = Edge::Unordered
   578                  }
   579              },
   581              IR::Sink { input: _, payload } => {
   582                  let ([in_edge], []) = unpack_edges!(1);
   584                  let mut keys_pin_order = false;
   585                  if let SinkTypeIR::Partitioned(options) = payload {
   586                      let mut eos = expr_order_simplifier!();
   587                      let ae_nodes_scratch = self.ae_nodes_scratch.get();
   589                      ae_nodes_scratch.extend(options.expr_irs_iter().map(|eir| eir.node()));
   590                      let observable = eos.simplify_projected_exprs(ae_nodes_scratch, false);
   593                      assert!(!observable.contains(O::INDEPENDENT));
   595                      keys_pin_order = eos.internally_observed_orders().contains(O::COLUMN);
   596                  }
   598                  if !keys_pin_order && (!payload.maintain_order() || in_edge.is_unordered()) {
   599                      *in_edge = Edge::Unordered;
   600                      payload.set_maintain_order(false);
   601                  }
   602              },
   604              #[cfg(feature = "python")]
   605              IR::PythonScan { .. } => {},
   607              IR::Scan { .. }
   608              | IR::DataFrameScan { .. }
   609              | IR::UnoptimizedDispatch { .. }
   610              | IR::Recursive { .. }
   611              | IR::WorkingTableScan { .. }
   612              | IR::Resolver { .. } => {},
   613              IR::SinkMultiple { .. } | IR::Invalid => unreachable!(),
   614          };
   616          false
   617      }
   619      fn unlink_node(&mut self, current_ir_node: Node, input_to_current_ir_node: Node) -> bool {
   620          let current_ir_node_edges = self
   621              .ir_node_to_edges_map
   622              .get(&IRNodeKey::new(current_ir_node, self.ir_arena))
   623              .unwrap();
   625          let IRNodeEdgeKeys {
   626              out_nodes,
   627              in_edges,
   628              ..
   629          } = current_ir_node_edges;
   631          assert_eq!(out_nodes.len(), 1);
   632          assert_eq!(in_edges.len(), 1);
   634          let current_in_edge_key = in_edges[0];
   636          let consumer_node = out_nodes[0];
   638          let mut iter = self
   639              .ir_arena
   640              .get_mut(consumer_node)
   641              .inputs_mut()
   642              .enumerate()
   643              .filter(|(_, node)| **node == current_ir_node);
   645          let (consumer_node_input_idx, node) = iter.next().unwrap();
   646          *node = input_to_current_ir_node;
   647          assert!(iter.next().is_none());
   648          drop(iter);
   650          let [
   651              Some(IRNodeEdgeKeys {
   652                  in_edges: consumer_node_in_edges,
   653                  ..
   654              }),
   655              Some(IRNodeEdgeKeys {
   656                  out_edges: out_edges_of_new_input_node,
   657                  out_nodes: out_nodes_of_new_input_node,
   658                  ..
   659              }),
   660          ] = self.ir_node_to_edges_map.get_disjoint_mut([
   661              &IRNodeKey::new(consumer_node, self.ir_arena),
   662              &IRNodeKey::new(input_to_current_ir_node, self.ir_arena),
   663          ])
   664          else {
   665              unreachable!()
   666          };
   668          let out_edge_idx_in_new_input_node = out_edges_of_new_input_node
   669              .iter()
   670              .position(|k| *k == current_in_edge_key)
   671              .unwrap();
   673          out_edges_of_new_input_node[out_edge_idx_in_new_input_node] =
   674              consumer_node_in_edges[consumer_node_input_idx];
   675          out_nodes_of_new_input_node[out_edge_idx_in_new_input_node] = consumer_node;
   677          true
   678      }
   679  }

let AExpr::Over {
                    function,
                    partition_by,
                    order_by,
                    mapping: _,
                } = self.expr_arena.get(current_ae_node)
                else {
                    unreachable!()
